// GENERATED by tools/audit/gen_series_routing_manifest.py -- do not edit.
//
// Calls every generated Series wrapper once under strict-unrouted mode and
// classifies the outcome ROUTED / UNROUTED / CRASHED. A CRASHED row means the
// synthetic arguments were lethal to a real kernel (still routed); only
// UNROUTED rows -- the strict-mode backstop error -- fail the gate, and only
// when not on the known_unrouted() allowlist. Writes the full classification
// to series_routing_manifest.txt in the run directory.

#include <catch2/catch_test_macros.hpp>

#include <pluss/codem/codem.h>
#include <pluss/codem/series_factory.h>

#include "CodeM/compat/Invoke.h"
#include "MSharp/RangeView.h"

#include <sys/wait.h>
#include <unistd.h>

#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <set>
#include <string>
#include <vector>

namespace {

using pluss::ScalarType;
using pluss::Series;
using pluss::make_series;

enum class R { ROUTED, UNROUTED, CRASHED };

struct Row { std::string key; R r; };
std::vector<Row>& rows() { static std::vector<Row> v; return v; }

const char* kManifestPath = "series_routing_manifest.txt";
std::ofstream& sink() {
  static std::ofstream s(kManifestPath, std::ios::trunc);
  return s;
}

Series probe_input() {
  return make_series(std::vector<double>{0.3, -0.7, 1.1, 0.4, -0.2, 0.9}, {2, 3})
      .to(ScalarType::Float64);
}

// Each probe runs in a forked child so a kernel that segfaults or aborts on
// the deliberately-wrong synthetic arguments is contained: the parent still
// records a verdict and moves on. The child reports its classification over a
// pipe; a child that dies by signal (or writes nothing) is CRASHED, which
// means "reached a real kernel that did not like the args" -- not a routing
// failure. Only the strict-mode backstop error is UNROUTED.
template <class F>
void probe(const std::string& name, const std::string& sig, F&& f) {
  const std::string key = name + sig;
  int fds[2];
  if (pipe(fds) != 0) { rows().push_back({key, R::CRASHED});
    sink() << "CRASHED\t" << key << "\tpipe() failed\n"; sink().flush(); return; }
  const pid_t pid = fork();
  if (pid == 0) {
    ::close(fds[0]);
    std::freopen("/dev/null", "w", stderr);
    std::string verdict = "ROUTED";
    std::string detail;
    try {
      (void)f();
    } catch (const std::exception& e) {
      const std::string w = e.what();
      const bool unrouted = w.find("Unrouted") != std::string::npos &&
                            w.find("strict mode") != std::string::npos;
      verdict = unrouted ? "UNROUTED" : "ROUTED";
      detail = w.substr(0, 160);
    } catch (...) {
      detail = "non-std exception";
    }
    std::string line = verdict + "\t" + key;
    if (!detail.empty()) line += "\t" + detail;
    const ssize_t wr = ::write(fds[1], line.data(), line.size());
    (void)wr;
    ::close(fds[1]);
    _exit(0);
  }
  ::close(fds[1]);
  std::string got;
  char buf[512];
  ssize_t n;
  while ((n = ::read(fds[0], buf, sizeof buf)) > 0) got.append(buf, static_cast<std::size_t>(n));
  ::close(fds[0]);
  int status = 0;
  ::waitpid(pid, &status, 0);
  R r;
  std::string outline;
  if (!got.empty() && !WIFSIGNALED(status)) {
    outline = got;
    r = got.rfind("UNROUTED\t", 0) == 0 ? R::UNROUTED : R::ROUTED;
  } else {
    r = R::CRASHED;
    outline = "CRASHED\t" + key + "\t" +
              (WIFSIGNALED(status)
                   ? std::string("fatal signal ") + std::to_string(WTERMSIG(status))
                   : std::string("child produced no verdict"));
  }
  rows().push_back({key, r});
  sink() << outline << "\n";
  sink().flush();
}

// Signatures known to be public-but-unimplemented today (the strict-mode
// backstop fires). Each must be either implemented or converted to a precise
// loud rejection; until then it is tracked here so the gate stays meaningful
// for everything else. Populated from the first manifest run.
const std::set<std::string>& known_unrouted() {
  static const std::set<std::string> s{
  };
  return s;
}

}  // namespace

